class Solution {
    public int calculate(String s){
        int result=0,last=0,number=0;
        char operator='+';
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(Character.isDigit(c))number=number*10+c-'0';
            if((!Character.isDigit(c)&&c!=' ')||i==s.length()-1){
                if(operator=='+'){
                    result+=last;
                    last=number;
                }else if(operator=='-'){
                    result+=last;
                    last=-number;
                }else if(operator=='*')last*=number;
                else last/=number;
                operator=c;
                number=0;
            }
        }
        return result+last;
    }
}

